def on_basic_type(self, type_specifiers, location):
    """ Handle basic type """
    if self.context.is_valid(type_specifiers):
        ctyp = self.context.get_type(type_specifiers)
    else:
        self.error('Invalid type specifiers', location)
    return ctyp
